"""
Streamlit frontend for the Palmistry & Tarot Intelligence Platform.

Run locally with:
    streamlit run frontend/app.py

Talks to the FastAPI backend over HTTP — set API_URL to point at it
(defaults to localhost:8000 for local dev; override via env var when
deployed, e.g. API_URL=https://your-api.onrender.com).
"""

import sys
from pathlib import Path as _Path

_PROJECT_ROOT = _Path(__file__).resolve().parent.parent

if str(_PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(_PROJECT_ROOT))

from database import (
    create_user,
    authenticate_user,
    save_reading,
    get_user_readings,
    update_username,
    update_email,
    update_password,
    delete_user,
)

import os
import base64
import json
import requests
import streamlit as st

API_URL = os.environ.get("API_URL", "http://localhost:8000")
_BG_IMAGE = "data:image/png;base64,"

st.set_page_config(
    page_title="The Reading — Palm & Tarot",
    page_icon="🔮",
    layout="centered",
    initial_sidebar_state="expanded",
)

# ---------------------------------------------------------------------------
# Theme — ink & parchment, brass hairlines, tarot-card lettering (Cinzel) for
# display/labels, EB Garamond for body. NOTE: some selectors below target
# Streamlit's data-testid hooks, which are reasonably stable but can shift
# between Streamlit versions — if a rule stops applying after an upgrade,
# check the new testid via your browser's inspector.
# ---------------------------------------------------------------------------
st.markdown("""
<style>
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600&family=EB+Garamond:ital,wght@0,400;0,500;1,400&display=swap');

:root {
    --ink:        #1C1B29;
    --ink-deep:   #131220;
    --parchment:  #F4ECD8;
    --parchment-2:#EBE0C4;
    --brass:      #C6A15B;
    --wine:       #7A2E38;
    --mist:       #A8A5C4;
}

/* page background */
[data-testid="stAppViewContainer"], [data-testid="stMain"] {
    background-image: linear-gradient(rgba(10, 5, 25, 0.42), rgba(10, 5, 25, 0.50)), url("__BG_IMAGE__");
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
}
[data-testid="stHeader"] { background: transparent; }

/* sidebar */
[data-testid="stSidebar"] {
    background: var(--ink-deep);
    border-right: 1px solid rgba(198,161,91,0.25);
}
[data-testid="stSidebar"] * { color: var(--mist) !important; font-family: 'EB Garamond', serif; }
[data-testid="stSidebar"] h1, [data-testid="stSidebar"] h2, [data-testid="stSidebar"] h3 {
    font-family: 'Cinzel', serif !important;
    color: var(--brass) !important;
    letter-spacing: 0.06em;
}

/* base typography */
html, body, [class*="css"] { font-family: 'EB Garamond', Georgia, serif; }
p, li, label, span, div { color: var(--parchment); }

/* main title block */
.reading-eyebrow {
    font-family: 'Cinzel', serif;
    letter-spacing: 0.3em;
    font-size: 0.72rem;
    color: var(--brass);
    text-transform: uppercase;
    text-align: center;
    margin-bottom: 0.3rem;
}
.reading-title {
    font-family: 'Cinzel', serif;
    font-size: 2.3rem;
    font-weight: 600;
    text-align: center;
    color: var(--parchment);
    letter-spacing: 0.04em;
    margin: 0 0 0.15rem 0;
}
.reading-subtitle {
    text-align: center;
    color: var(--mist);
    font-style: italic;
    font-size: 1.05rem;
    margin-bottom: 1.6rem;
}
.hairline {
    border: none;
    border-top: 1px solid rgba(198,161,91,0.35);
    margin: 1.6rem 0;
}

/* section labels */
.section-eyebrow {
    font-family: 'Cinzel', serif;
    letter-spacing: 0.22em;
    font-size: 0.75rem;
    text-transform: uppercase;
    color: var(--brass);
    margin: 0.2rem 0 0.6rem 0;
}

/* parchment panel (form + palm findings + interpretation cards) */
.parchment-panel {
    background: var(--parchment);
    color: var(--ink);
    border-radius: 4px;
    border: 1px solid var(--brass);
    box-shadow: 0 8px 24px rgba(0,0,0,0.35);
    padding: 1.6rem 1.8rem;
    margin-bottom: 1.4rem;
}
.parchment-panel p, .parchment-panel li, .parchment-panel span, .parchment-panel div { color: var(--ink) !important; }
/* Main reading quote banner */
.reading-quote-banner {
    background: var(--parchment);
    color: var(--wine);
    border: 1px solid var(--brass);
    border-radius: 4px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.35);

    padding: 1.15rem 1.8rem;
    margin: 0 auto 1.8rem auto;

    text-align: center;

    font-family: 'EB Garamond', Georgia, serif;
    font-style: italic;
    font-weight: 700;
    font-size: 1.35rem;
    line-height: 1.45;
    letter-spacing: 0.015em;
}

/* Keep the reading form clean */
.reading-form-label {
    display: none !important;
}

/* Main reading question input */
div[data-testid="stTextInput"] input {
    color: var(--ink) !important;
    font-family: 'EB Garamond', Georgia, serif !important;
    font-size: 1.05rem !important;
}

/* Visible placeholder */
div[data-testid="stTextInput"] input::placeholder {
    color: #7A2E38 !important;
    opacity: 0.75 !important;
    font-family: 'EB Garamond', Georgia, serif !important;
    font-style: italic !important;
    font-size: 1.05rem !important;
}

/* Keep placeholder visible when the input is focused */
div[data-testid="stTextInput"] input:focus::placeholder {
    color: #7A2E38 !important;
    opacity: 0.55 !important;
}




/* Reading result headings */
.parchment-panel h4 {
    color: #7A2E38 !important;
    font-family: 'Cinzel', Georgia, serif !important;
    font-weight: 700 !important;
    letter-spacing: 0.05em;
}

/* palm line row */
.line-row { display:flex; justify-content:space-between; align-items:baseline;
    padding: 0.5rem 0; border-bottom: 1px dotted rgba(122,46,56,0.35); }
.line-row:last-child { border-bottom: none; }
.line-glyph { font-size: 1.1rem; color: var(--wine); width: 1.6rem; }
.line-name { font-family:'Cinzel', serif; font-size:0.8rem; letter-spacing:0.08em;
    color: var(--wine); text-transform: uppercase; }
.line-finding { color: var(--ink); font-style: italic; text-align:right; flex:1; margin-left:1rem; }

/* tarot card panels */
.tarot-card {
    background: linear-gradient(180deg, var(--parchment) 0%, var(--parchment-2) 100%);
    border: 1.5px solid var(--brass);
    border-radius: 6px;
    padding: 1.1rem 0.9rem 1.3rem 0.9rem;
    text-align: center;
    box-shadow: 0 8px 20px rgba(0,0,0,0.4);
    min-height: 210px;
    position: relative;
}
.tarot-card::before {
    content: "✦";
    display:block;
    color: var(--brass);
    font-size: 0.9rem;
    margin-bottom: 0.4rem;
}
.tarot-numeral {
    font-family:'Cinzel', serif;
    color: var(--brass);
    font-size: 0.75rem;
    letter-spacing: 0.25em;
}
.tarot-position {
    font-family:'Cinzel', serif;
    color: var(--wine);
    font-size: 0.68rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 0.5rem;
}
.tarot-name {
    font-family:'Cinzel', serif;
    color: var(--ink);
    font-size: 1.02rem;
    font-weight: 600;
    line-height: 1.25;
    margin-bottom: 0.25rem;
}
.tarot-orientation {
    font-size: 0.8rem;
    font-style: italic;
    color: var(--wine);
    margin-bottom: 0.6rem;
}
.tarot-keywords {
    font-size: 0.78rem;
    color: #55503f;
    letter-spacing: 0.02em;
}

/* buttons */
.stButton > button, .stFormSubmitButton > button, [data-testid="stDownloadButton"] > button {
    font-family: 'Cinzel', serif;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    font-size: 0.78rem;
    background: var(--wine);
    color: var(--parchment);
    border: 1px solid var(--brass);
    border-radius: 3px;
    padding: 0.6rem 1.4rem;
    transition: all 0.15s ease;
}
.stButton > button:hover, .stFormSubmitButton > button:hover, [data-testid="stDownloadButton"] > button:hover {
    background: var(--brass);
    color: var(--ink-deep);
    border-color: var(--brass);
}

/* text input + file uploader inside the parchment form */
[data-testid="stTextInput"] input {
    background: #FFFCF3 !important;
    color: var(--ink) !important;
    border: 1px solid rgba(122,46,56,0.3) !important;
    font-family: 'EB Garamond', serif;
    font-size: 1.02rem;
}
[data-testid="stFileUploaderDropzone"] {
    background: #FFFCF3 !important;
    border: 1.5px dashed var(--wine) !important;
    border-radius: 4px;
}
[data-testid="stFileUploaderDropzone"] * { color: var(--ink) !important; }
[data-testid="stFileUploaderDropzone"] button {
    background: var(--wine) !important;
    color: var(--parchment) !important;
    border-radius: 3px !important;
    font-family: 'EB Garamond', serif !important;
    text-transform: none !important;
    letter-spacing: 0 !important;
}

/* footer note */
.reading-footer {
    text-align:center;
    color: var(--mist);
    font-size: 0.8rem;
    font-style: italic;
    margin-top: 2.5rem;
    padding-top: 1rem;
    border-top: 1px solid rgba(198,161,91,0.2);
}
</style>
""".replace("__BG_IMAGE__", _BG_IMAGE), unsafe_allow_html=True)

# ============================================================
# PAGE-SPECIFIC BACKGROUND OVERRIDE
# ============================================================

# Page 1 + Page 2
#     assets/intro_background.png
#
# Page 3 + Page 4
#     assets/login_dashboard_background.png
#
# Page 5 / Reading
#     Existing background is preserved.
# ============================================================

_bg_intro_path = _PROJECT_ROOT / "assets" / "intro_background.png"
_bg_account_path = _PROJECT_ROOT / "assets" / "login_dashboard_background.png"

# Main Reading Page background
_bg_reading_path = _PROJECT_ROOT / "assets" / "main_reading_background.png"

# User Dashboard background
_bg_dashboard_path = _PROJECT_ROOT / "assets" / "dashboard_background.jpeg"

_bg_intro_data = ""
_bg_account_data = ""
_bg_reading_data = ""
_bg_dashboard_data = ""

try:
    import base64 as _bg_base64

    if _bg_intro_path.exists():
        _bg_intro_data = _bg_base64.b64encode(
            _bg_intro_path.read_bytes()
        ).decode("ascii")

    if _bg_account_path.exists():
        _bg_account_data = _bg_base64.b64encode(
            _bg_account_path.read_bytes()
        ).decode("ascii")

    if _bg_reading_path.exists():
        _bg_reading_data = _bg_base64.b64encode(
            _bg_reading_path.read_bytes()
        ).decode("ascii")

    if _bg_dashboard_path.exists():
        _bg_dashboard_data = _bg_base64.b64encode(
            _bg_dashboard_path.read_bytes()
        ).decode("ascii")

except Exception:
    _bg_intro_data = ""
    _bg_account_data = ""
    _bg_reading_data = ""
    _bg_dashboard_data = ""


_intro_seen_bg = st.session_state.get(
    "intro_seen",
    False,
)

_how_seen_bg = st.session_state.get(
    "how_it_works_seen",
    False,
)

_show_login_bg = st.session_state.get(
    "show_login",
    False,
)

_show_dashboard_bg = st.session_state.get(
    "show_user_dashboard",
    False,
)


# Determine which page is currently being displayed.

if not _intro_seen_bg:

    # PAGE 1 — INTRO
    _selected_bg_data = _bg_intro_data

elif not _how_seen_bg and not _show_login_bg:

    # PAGE 2 — ELABORATE INTRO / HOW IT WORKS
    _selected_bg_data = _bg_intro_data

elif _show_login_bg:

    # PAGE 3 — LOGIN
    _selected_bg_data = _bg_account_data

elif _show_dashboard_bg:

    # PAGE 4 — USER DASHBOARD
    _selected_bg_data = _bg_dashboard_data

else:

    # PAGE 5 — MAIN READING PAGE
    _selected_bg_data = _bg_reading_data


if _selected_bg_data:

    # Dashboard uses JPEG; all other selected backgrounds are PNG.
    if _show_dashboard_bg:
        _bg_mime = "image/jpeg"
    else:
        _bg_mime = "image/png"

    st.markdown(
        f"""
        <style>
        [data-testid="stAppViewContainer"],
        [data-testid="stMain"] {{
            background-image:
                linear-gradient(
                    rgba(10, 5, 25, 0.42),
                    rgba(10, 5, 25, 0.50)
                ),
                url("data:{_bg_mime};base64,{_selected_bg_data}");

            background-size: cover !important;
            background-position: center center !important;
            background-attachment: fixed !important;
            background-repeat: no-repeat !important;
        }}
        </style>
        """,
        unsafe_allow_html=True,
    )

# PAGE_SPECIFIC_BACKGROUND_OVERRIDE



# ---------------------------------------------------------------------------
# Sidebar — how it works + housekeeping
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# Sidebar — profile / how it works + housekeeping
# ---------------------------------------------------------------------------

with st.sidebar:

    if st.session_state.get("profile_panel_open", False):

        st.markdown("## PROFILE")

        if st.session_state.get("logged_in", False):

            profile_name = st.session_state.get(
                "user_name",
                "User",
            )

            profile_email = st.session_state.get(
                "user_email",
                "",
            )

            st.markdown(
                f"### {profile_name}",
                unsafe_allow_html=True,
            )

            st.caption(profile_email)

            if st.button(
                "My Profile",
                use_container_width=True,
                key="profile_my_profile",
            ):
                st.session_state["profile_section"] = "profile"
                st.rerun()

            # ------------------------------------------------
            # MY PROFILE
            # ------------------------------------------------

            if st.session_state.get("profile_section") == "profile":

                st.markdown("---")
                st.markdown("### Account Settings")

                # --------------------------------------------
                # USERNAME
                # --------------------------------------------

                st.markdown("#### Username")

                new_username = st.text_input(
                    "Username",
                    value=st.session_state.get(
                        "user_name",
                        "",
                    ),
                    key="profile_new_username",
                )

                if st.button(
                    "Save Username",
                    use_container_width=True,
                    key="save_profile_username",
                ):

                    success, message = update_username(
                        st.session_state["user_id"],
                        new_username,
                    )

                    if success:

                        st.session_state["user_name"] = (
                            new_username.strip()
                        )

                        st.success(message)
                        st.rerun()

                    else:

                        st.error(message)


                # --------------------------------------------
                # EMAIL
                # --------------------------------------------

                st.markdown("#### Email")

                new_email = st.text_input(
                    "Email address",
                    value=st.session_state.get(
                        "user_email",
                        "",
                    ),
                    key="profile_new_email",
                )

                if st.button(
                    "Save Email",
                    use_container_width=True,
                    key="save_profile_email",
                ):

                    success, message = update_email(
                        st.session_state["user_id"],
                        new_email,
                    )

                    if success:

                        st.session_state["user_email"] = (
                            new_email.strip().lower()
                        )

                        st.success(message)
                        st.rerun()

                    else:

                        st.error(message)


                # --------------------------------------------
                # PASSWORD
                # --------------------------------------------

                st.markdown("#### Change Password")

                current_password = st.text_input(
                    "Current password",
                    type="password",
                    key="profile_current_password",
                )

                new_password = st.text_input(
                    "New password",
                    type="password",
                    key="profile_new_password",
                )

                confirm_password = st.text_input(
                    "Confirm new password",
                    type="password",
                    key="profile_confirm_password",
                )

                if st.button(
                    "Change Password",
                    use_container_width=True,
                    key="save_profile_password",
                ):

                    if not current_password:

                        st.error(
                            "Please enter your current password."
                        )

                    elif not new_password:

                        st.error(
                            "Please enter a new password."
                        )

                    elif new_password != confirm_password:

                        st.error(
                            "The new passwords do not match."
                        )

                    elif len(new_password) < 8:

                        st.error(
                            "Password must contain at least 8 characters."
                        )

                    else:

                        # Verify the current password first.
                        current_user = authenticate_user(
                            st.session_state["user_email"],
                            current_password,
                        )

                        if current_user is None:

                            st.error(
                                "Current password is incorrect."
                            )

                        else:

                            success, message = update_password(
                                st.session_state["user_id"],
                                new_password,
                            )

                            if success:

                                st.success(
                                    "Password changed successfully."
                                )

                                st.rerun()

                            else:

                                st.error(message)


                st.markdown("---")

                if st.button(
                    "Close Profile",
                    use_container_width=True,
                    key="close_profile_settings",
                ):

                    st.session_state["profile_section"] = None
                    st.rerun()


            if st.button(
                "View Dashboard",
                use_container_width=True,
                key="profile_dashboard",
            ):
                st.session_state["profile_panel_open"] = False
                st.session_state["show_user_dashboard"] = True
                st.session_state["show_login"] = False
                st.rerun()

            st.markdown("---")

            if st.button(
                "Logout",
                use_container_width=True,
                key="profile_logout",
            ):
                st.session_state["logged_in"] = False
                st.session_state["user_id"] = None
                st.session_state["user_name"] = None
                st.session_state["user_email"] = None
                st.session_state["profile_panel_open"] = False
                st.session_state["show_user_dashboard"] = False
                st.session_state["show_login"] = False
                st.rerun()

            st.markdown("---")

            if st.button(
                "Delete Account",
                use_container_width=True,
                key="profile_delete_account",
            ):
                st.session_state["delete_account_confirm"] = True
                st.rerun()

        else:

            st.info(
                "Please log in or create an account "
                "to access your profile."
            )

        st.markdown("---")

        if st.button(
            "Close",
            use_container_width=True,
            key="profile_close",
        ):
            st.session_state["profile_panel_open"] = False
            st.rerun()

    else:

        st.markdown("### The Reading")

        st.markdown(
            "**I. Upload** a clear photo of your open palm, lines visible, "
            "good light, no gloves or jewelry over the lines.\n\n"
            "**II. Ask** what you'd like the reading to focus on.\n\n"
            "**III. Receive** your palm lines read, three tarot cards drawn, "
            "and both woven into one interpretation."
        )

        st.markdown("---")

        st.markdown(
            "<span style='font-size:0.78rem;'>"
            "For reflection and entertainment. "
            "Not a substitute for professional advice."
            "</span>",
            unsafe_allow_html=True,
        )

        if st.session_state.get("last_result"):

            st.markdown("---")

            if st.button(
                "Read Another Palm",
                use_container_width=True,
            ):
                st.session_state.pop("last_result", None)
                st.rerun()


# WELCOME PAGE
# ---------------------------------------------------------------------------

st.markdown(
    """
    <style>
    .welcome-heading {
        text-align: center;
        padding-top: 4.5rem;
        padding-bottom: 1.5rem;
    }

    .welcome-eyebrow {
        font-family: 'Cinzel', serif;
        letter-spacing: 0.22em;
        text-transform: uppercase;
        font-size: 0.8rem;
        color: #C6A15B;
        margin-bottom: 1rem;
    }

    .welcome-title {
        font-family: 'Cinzel', serif;
        font-size: 3.2rem;
        color: #F1E6C8;
        letter-spacing: 0.08em;
    }

    .welcome-disclaimer {
        max-width: 650px;
        margin: 1.5rem auto 0 auto;
        text-align: center;
        font-family: 'EB Garamond', Georgia, serif;
        font-size: 0.95rem;
        line-height: 1.6;
        color: #A8A5C4;
        font-style: italic;
    }
    </style>
    """,
    unsafe_allow_html=True,
)

# WELCOME_PAGE_START

import time

if "show_login" not in st.session_state:
    st.session_state["show_login"] = False

if "profile_panel_open" not in st.session_state:
    st.session_state["profile_panel_open"] = False

if "profile_section" not in st.session_state:
    st.session_state["profile_section"] = None

if "delete_account_confirm" not in st.session_state:
    st.session_state["delete_account_confirm"] = False

if "intro_seen" not in st.session_state:
    st.session_state["intro_seen"] = False

if "intro_animation_done" not in st.session_state:
    st.session_state["intro_animation_done"] = False


if not st.session_state["intro_seen"]:

    # ---------------------------------------------------------
    # Welcome page styling
    # ---------------------------------------------------------

    st.markdown(
        """
        <style>
        .welcome-eyebrow-clean {
            text-align: center;
            font-family: 'Cinzel', Georgia, serif;
            font-size: 0.82rem;
            letter-spacing: 0.32em;
            text-transform: uppercase;
            color: #C6A15B;
            margin-top: 3rem;
            margin-bottom: 1.2rem;
        }

        .welcome-title-clean {
            text-align: center;
            font-family: 'Cinzel', Georgia, serif;
            font-size: 4.2rem;
            font-weight: 600;
            letter-spacing: 0.12em;
            text-transform: uppercase;
            color: #F3E7C5;
            text-shadow: 0 0 18px rgba(198,161,91,0.25);
            margin-bottom: 0.8rem;
        }

        .welcome-line-clean {
            width: 220px;
            height: 1px;
            margin: 0 auto 2rem auto;
            background: #C6A15B;
            opacity: 0.7;
        }

        .welcome-text-clean {
            max-width: 780px;
            margin: 0 auto;
            text-align: center;
            font-family: 'EB Garamond', Georgia, serif;
            font-size: 1.28rem;
            line-height: 1.85;
            color: #F0E6CF;
        }

        .welcome-disclaimer-clean {
            max-width: 650px;
            margin: 1.6rem auto 0 auto;
            text-align: center;
            font-family: 'EB Garamond', Georgia, serif;
            font-size: 0.95rem;
            line-height: 1.6;
            color: #B8B3C8;
            font-style: italic;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

    # ---------------------------------------------------------
    # Beautiful title
    # ---------------------------------------------------------

    st.markdown(
        '<div class="welcome-eyebrow-clean">Palm · Tarot · Intelligence</div>',
        unsafe_allow_html=True,
    )

    st.markdown(
        '<div class="welcome-title-clean">The Reading</div>',
        unsafe_allow_html=True,
    )

    st.markdown(
        '<div class="welcome-line-clean"></div>',
        unsafe_allow_html=True,
    )

    # ---------------------------------------------------------
    # Introduction
