# CHARACTER_ANIMATION_HELPER

def character_typewriter(text, total_seconds=5.5):
    """
    Display text one character at a time.

    The complete sentence takes approximately
    total_seconds to finish.
    """

    import time
    import html

    placeholder = st.empty()

    clean_text = text.strip()

    if not clean_text:
        return

    delay = total_seconds / max(len(clean_text), 1)

    visible = ""

    for character in clean_text:

        visible += character

        escaped = html.escape(visible)
        escaped = escaped.replace("\n", "<br>")

        placeholder.markdown(
            f"""
            <div class="info-detail">
                {escaped}
                <span style="
                    color:#C6A15B;
                    font-weight:bold;
                ">▌</span>
            </div>
            """,
            unsafe_allow_html=True,
        )

        time.sleep(delay)

    # Remove cursor after completion

    escaped = html.escape(clean_text)
    escaped = escaped.replace("\n", "<br>")

    placeholder.markdown(
        f"""
        <div class="info-detail">
            {escaped}
        </div>
        """,
        unsafe_allow_html=True,
    )


# CHARACTER_ANIMATION_HELPER


